  for month in 1 to 12 {
    balance = starting_balance * (1 + monthly_rate) ^ month
    output month, balance
  }
}

// FinRule: Retail Bank Home Loan Underwriting & Stress Test
model "Home Loan DTI Stress Test" {
  loan_amount = 4000000
  annual_rate = 0.085
  tenure_years = 20
  total_months = tenure_years * 12
  monthly_rate = annual_rate / 12

  customer_monthly_income = 120000
  max_allowed_dti = 0.45

  // Calculate fixed monthly EMI using built-in PMT function
  monthly_emi = PMT(monthly_rate, total_months, loan_amount)
  dti_ratio = monthly_emi / customer_monthly_income

  remaining_balance = loan_amount

  for month in 1 to 24 {
    interest_fee = remaining_balance * monthly_rate
    principal_paid = monthly_emi - interest_fee
    remaining_balance = remaining_balance - principal_paid

    output month, monthly_emi, principal_paid, interest_fee, remaining_balance
  }
}

// Scenario 1: RBI Rate Hike (Stress Test)
scenario "RBI Rate Hike (+2%)" {
  annual_rate = 0.105
}

// Scenario 2: Customer Gets 15% Salary Increment
scenario "Salary Promotion (+15%)" {
  customer_monthly_income = 138000
}

